  all:[["Honnêteté du candidat",61],["Projet proposé",60],["Valeurs défendues",58],["Souhait de voir ce candidat gagner",56],["Prise en compte de ses préoccupations",55],["Idées nouvelles",54],["Présence de son candidat au second tour",51],["Capacité à battre Jean-Luc Mélenchon au second tour",51],["Empêcher la qualification de Jean-Luc Mélenchon",51],["Capacité à rassembler",47],["Personnalité du candidat",46],["Représentation de la France à l'étranger",45],["Parti ou mouvement",42],["Expérience et parcours",42],["Empêcher la qualification d'un autre candidat",41],["Capacité à battre Marine Le Pen au second tour",41],["Bilan du candidat",39],["Empêcher la qualification de Marine Le Pen",37],["Notoriété du candidat",33],["Personnalités qui le soutiennent",31],["Score dans les sondages",30]],
